				clamp = { min = { value = 1 subtract = RUS_military_anger } max = { value = 10 subtract = RUS_military_anger } }
			}
		}

		if = {
			limit = {
				OR = {
					NOT = { has_variable = RUS_military_anger } #bypass the check when initialising
					NOT = { check_variable = { RUS_anger_change = 0 } }
				}
			}
			if = {
				limit = { check_variable = { RUS_anger_change > 0 } }
				custom_effect_tooltip = RUS_increase_mil_anger
			}
			else = {
				custom_effect_tooltip = RUS_decrease_mil_anger
			}

			# set the new variables
			add_to_variable = { RUS_military_anger = RUS_anger_change }
			add_to_variable = { RUS_military_anger_stability = { value = -0.01 multiply = RUS_anger_change } }
			add_to_variable = { RUS_military_anger_morale = { value = -0.03 multiply = RUS_anger_change } }
		}

		# events
		hidden_effect = {
			if = {
				limit = { check_variable = { RUS_military_anger > 9 } }
				country_event = { id = russia_democratic_events.103 days = 4 random_days = 4 } #Coup in the Kremlin
			}
			else_if = {
				limit = { check_variable = { RUS_military_anger > 7 } }
				country_event = { id = russia_democratic_events.102 days = 4 random_days = 4 } #The Generals' Letter
			}
			else_if = {
				limit = { check_variable = { RUS_military_anger > 5 } }
				country_event = { id = russia_democratic_events.101 days = 4 random_days = 4 } #A Visit from the General-Fieldmarshal
			}
			else_if = {
				limit = { check_variable = { RUS_military_anger > 3 } }
				country_event = { id = russia_democratic_events.100 days = 4 random_days = 4 } #Rightwing Exploiting Anger
			}
		}
	}
}

